style.css:
/* Barbie-inspired basic style */
body {
    background-color: #ffb6c1; /* Light Barbie pink */
    color: #111;
    font-family: Arial, Helvetica, sans-serif !important; /* Basic safe font */
}

/* Links */
a {
    color: #ff7f50; /* Summer orange */
    text-decoration: underline;
    transition: all 0.3s;
}

a:hover {
    text-shadow: 0 0 8px #ff7f50;
}

/* Buttons */
button, input[type="button"], input[type="submit"] {
    border: none;
    border-radius: 12px;
    padding: 6px 12px;
    cursor: pointer;
    transition: all 0.3s;
    color: #fff;
    /* Random Barbie color for each button */
    background-color: #ff69b4; /* default pink fallback */
}

